import{z as d,x as A,o,c as B,q as t,j as n,D as e,d as s,s as E,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"Linux 提权路径","description":"","frontmatter":{"title":"Linux 提权路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linux-privesc.md","filePath":"cs/linux-privesc.md","lastUpdated":1791063341000}'),p={name:"cs/linux-privesc.md"};function D(u,a,c,S,h,m){const r=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="linux-提权路径" tabindex="-1">Linux 提权路径 <a class="header-anchor" href="#linux-提权路径" aria-label="Permalink to &quot;Linux 提权路径&quot;">​</a></h1><div class="epigraph"><p>从普通用户到特权，常见路是：SUID 程序缺陷、能力过宽、sudo 规则、可写的服务配置、内核漏洞。硬化是收这些面，而不是研究如何走完一条路。</p><footer>—— 据 Chen, Wagner 和 Dean 对 SUID 的讨论；Linux capabilities(7)；对照 Anderson</footer></div><p>上一课<a href="/cs/selinux-type-enforcement">SELinux</a>假定类型策略在位；策略之外还有一整层本地提权面。缺口是<strong>策略之外的提权面</strong>：文件模式、能力、sudo。本课列机制与硬化，不给提权利用步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>setuid 位让程序以文件属主身份跑：属主是 root，程序里任何一个洞即属主权——拿到普通 shell 的敌手第一件事就是翻 SUID 清单。capabilities 把 root 劈成 CAP_NET_ADMIN 等细项，方向正确，但给错仍过大：给守护进程 CAP_SYS_ADMIN 几乎等于把 root 还给它。sudo 规则是第三张面：<code>NOPASSWD</code> 加通配符的规则常被参数注入绕过。缺口是盘点 SUID、收能力、审 sudo，外加服务配置文件不可被服务账号写。</p><h3 id="内核" tabindex="-1">内核 <a class="header-anchor" href="#内核" aria-label="Permalink to &quot;内核&quot;">​</a></h3><p>内核洞是另一条路：普通用户即可打内核洞直达特权，不依赖任何配置错误。窗口问题补丁管理课已强调。本课不讨论利用。</p><p><span class="marginnote">术语翻译：SUID（setuid 位）是「运行此程序时暂时换上文件属主身份」的开关。属主是 root 时，程序里任何一个内存安全洞都等于把 root 身份拱手让人——所以拿到 shell 的敌手第一件事就是翻 SUID 清单。</span></p><p><span class="marginnote">capabilities(7)。禁止提权教程。Windows Kerberos 下一课换域身份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬化清单四项：定期找 SUID/SGID 文件并逐个问为什么需要；<code>getcap</code> 查文件能力并白名单化；服务配置收成 root 属主、服务账号只读；sudo 禁无交互授权与通配符、命令写绝对路径。防御者清点这些面与攻击者翻找路径同源——容器逃逸（后课）翻的也是同一批，这边收紧那边同样受益。</p><p><span class="marginnote">常见误区：以为 sudo 限定了命令就安全。<code>sudo lsof *</code> 这类通配符规则可被参数注入成别的选项甚至任意命令；硬化要求命令写绝对路径、禁通配符、禁 NOPASSWD 式免交互授权。</span></p>',13)),(o(),n(l,null,{default:e(()=>[E(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E6%99%AE%E9%80%9A%E7%94%A8%E6%88%B7%22%5D%20--%3E%20SUID%5B%22SUID%20%E6%88%96%E8%BF%87%E5%AE%BD%E8%83%BD%E5%8A%9B%22%5D%0A%20%20USER%20--%3E%20SUDO%5B%22sudo%20%E8%A7%84%E5%88%99%22%5D%0A%20%20SUID%20--%3E%20HARD%5B%22%E7%9B%98%E7%82%B9%E5%B9%B6%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[s("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"最小特权在 Unix 上由两层承载：文件模式位是粗粒度的「程序换身份」，capabilities 是细粒度的「进程持单项特权」。失败模式都在授予侧：位给多了收不回，能力给了没有落盘的审计。硬化缩小这些面，但最小特权不等于零特权——审计要回答「谁还能拿到特权」，而不是「有没有特权」。域环境下一课用票据代替本地 root 叙事。",-1)),(o(),n(l,null,{default:e(()=>[E(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20SUID%5B%22SUID%20root%20%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20A1%5B%22%E9%80%90%E4%B8%AA%E7%9B%98%E7%82%B9%EF%BC%9A%E8%BF%98%E9%9C%80%E8%A6%81%E5%90%97%22%5D%0A%20%20FCAP%5B%22%E8%BF%87%E5%AE%BD%E7%9A%84%E6%96%87%E4%BB%B6%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20A2%5B%22getcap%20%E6%B8%85%E7%82%B9%E5%B9%B6%E7%99%BD%E5%90%8D%E5%8D%95%22%5D%0A%20%20SUDOR%5B%22NOPASSWD%20%E5%8A%A0%E9%80%9A%E9%85%8D%E7%AC%A6%E7%9A%84%20sudo%22%5D%20--%3E%20A3%5B%22%E7%BB%9D%E5%AF%B9%E8%B7%AF%E5%BE%84%E3%80%81%E5%8E%BB%E9%80%9A%E9%85%8D%E7%AC%A6%22%5D%0A%20%20CFG%5B%22%E6%9C%8D%E5%8A%A1%E5%8F%AF%E5%86%99%E8%87%AA%E5%B7%B1%E7%9A%84%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20A4%5B%22%E9%85%8D%E7%BD%AE%E6%94%B6%E5%BD%92%20root%EF%BC%8C%E6%9C%8D%E5%8A%A1%E5%8F%AA%E8%AF%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">直觉类比：提权面像没收拾好的钥匙——SUID 是别人忘在锁里的钥匙，sudo 通配符是「谁都可以拿」的备用钥匙，可写配置是让客人自己改门锁密码；硬化就是把每把钥匙登记、收回或锁进抽屉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零利用：机制、盘点命令与硬化规则可写，提权步骤不写。Windows Kerberos 攻击下一课讲协议失败模式与防御，不给操作步骤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE 之外，SUID/能力/sudo 仍是提权面。</li><li>硬化：盘点、收缩、只读配置。</li><li>内核窗口走补丁，不走利用课。</li><li>下一课 Kerberos 攻击面。</li><li>出处：Linux capabilities(7)；Anderson；Chen, Wagner and Dean。</li></ul>',5))])}const f=d(p,[["render",D]]);export{x as __pageData,f as default};
